public TFMListConfiguration getList()
{
    TFMListConfiguration				listConfig	= TFMListConfiguration::Construct(listName);
    TFMListRow							row			= listConfig.addRow();
    TFMListColumn						column		= row.makeColumn(100);

    column.addElement(TFMListTextElement::ConstructTextElement('{DisplayLine1}',TFMFonts::FindOrCreateFromProperties('contentFontBold',TFMFontSizes::medium,true,false,'').id));
    column.addElement(TFMListImageElement::ConstructImageElement('{imageId}','',100,0));
    column.addElement(TFMListTextElement::ConstructTextElement('{DisplayLine2}',TFMFonts::FindOrCreateFromProperties('smallFont',TFMFontSizes::small,false,false,'').id));
    return listConfig;
}
